int len[MAX_WORDS];

int can_fit(int start, int end, int space) {
    // check if words[start..end] can fit in one line with given max space
    int total_len = 0;
    for (int i = start; i <= end; i++) total_len += len[i];
    int gaps = end - start;
    if (gaps == 0) return total_len <= W;
    // need total_len + gaps * space <= W
    if (total_len + gaps * space > W) return 0;
    // also need to be able to distribute remaining spaces
    int remaining = W - total_len;
    // each gap gets at least space, so remaining >= gaps * space
    // already checked above
    // also need to ensure we can fill exactly
    return 1;
}

int min_max_spaces() {
    // binary search on answer
    int lo = 1, hi = W, ans = W;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        // greedy packing with max space = mid
        int line_start = 0;
        int ok = 1;
        while (line_start < n) {
            int line_end = line_start;
            int total_len = len[line_start];
            // try to add as many words as possible
            while (line_end + 1 < n) {
                int new_total = total_len + 1 + len[line_end+1]; // at least 1 space
                if (new_total <= W) {
                    total_len = new_total;
                    line_end++;
                } else break;
            }
            // now we have a candidate line from line_start to line_end
            // check if we can justify it with max space = mid
            if (!can_fit(line_start, line_end, mid)) {
                ok = 0;
                break;
            }
            line_start = line_end + 1;
        }
        if (ok) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return ans;
}

