#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 1000000000

typedef struct {
    char *s;
    int len;
} Word;

static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int W;
    if (scanf("%d", &W) != 1) return 0;

    int cap = 128, n = 0;
    Word *words = (Word *)malloc(sizeof(Word) * cap);

    char buf[10005];
    while (scanf("%10000s", buf) == 1) {
        if (n == cap) {
            cap *= 2;
            words = (Word *)realloc(words, sizeof(Word) * cap);
        }
        int len = (int)strlen(buf);
        words[n].s = (char *)malloc(len + 1);
        strcpy(words[n].s, buf);
        words[n].len = len;
        n++;
    }

    if (n == 0) {
        free(words);
        return 0;
    }

    int *pref = (int *)malloc(sizeof(int) * (n + 1));
    pref[0] = 0;
    for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + words[i].len;

    /* cost[i][j]:
       words i..j on one line.
       For non-last line: must exactly fill width W with at least one space between words,
       first word at col 1 and last word ending at col W.
       Cost = maximum gap length on that line.
       For last line: only need at least one space, no right justification.
       Cost = 1 if more than one word, else 0.
       If impossible, INF.
    */
    int **cost = (int **)malloc(sizeof(int *) * n);
    for (int i = 0; i < n; i++) {
        cost[i] = (int *)malloc(sizeof(int) * n);
        for (int j = 0; j < n; j++) cost[i][j] = INF;
    }

    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            int k = j - i + 1;
            int letters = pref[j + 1] - pref[i];
            int minWidth = letters + (k - 1);
            if (j == n - 1) {
                if (minWidth <= W) {
                    cost[i][j] = (k == 1 ? 0 : 1);
                }
            } else {
                if (k == 1) {
                    if (letters == W) cost[i][j] = 0;
                } else {
                    if (minWidth <= W) {
                        int spaces = W - letters;   /* total spaces across k-1 gaps */
                        int gaps = k - 1;
                        if (spaces >= gaps) {
                            int mx = (spaces + gaps - 1) / gaps; /* ceil */
                            cost[i][j] = mx;
                        }
                    }
                }
            }
        }
    }

    int *dp = (int *)malloc(sizeof(int) * (n + 1));
    int *nxt = (int *)malloc(sizeof(int) * (n + 1));
    dp[n] = 0;
    nxt[n] = -1;

    for (int i = n - 1; i >= 0; i--) {
        dp[i] = INF;
        nxt[i] = -1;
        for (int j = i; j < n; j++) {
            if (cost[i][j] == INF || dp[j + 1] == INF) continue;
            int val = max(cost[i][j], dp[j + 1]);
            if (val < dp[i]) {
                dp[i] = val;
                nxt[i] = j + 1;
            }
        }
    }

    int answer = dp[0];
    printf("%d\n", answer);

    /* cleanup */
    for (int i = 0; i < n; i++) free(words[i].s);
    for (int i = 0; i < n; i++) free(cost[i]);
    free(cost);
    free(pref);
    free(dp);
    free(nxt);
    free(words);

    return 0;
}

