    cin.tie(NULL);

    int W;
    cin >> W;

    vector<string> words;
    string word;
    while (cin >> word) {
        words.push_back(word);
    }

    int n = words.size();

    // dp[i] = minimal possible maximum gap for words[i..n-1]
    // We'll binary search on the answer
    vector<int> len(n);
    for (int i = 0; i < n; i++) {
        len[i] = words[i].length();
    }

    // Binary search for minimal possible max gap
    int lo = 0, hi = W;
    int ans = W;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;

        // Check if we can achieve max gap <= mid
        vector<int> dp(n + 1, INT_MAX);
        dp[n] = 0;  // base case: no words left, max gap = 0

        for (int i = n - 1; i >= 0; i--) {
            int total_len = 0;
            int words_in_line = 0;

            for (int j = i; j < n; j++) {
                total_len += len[j];
                words_in_line++;

                if (j > i) total_len++;  // at least one space between words

                if (total_len > W) break;

                if (j == n - 1) {
                    // Last line - no need to justify
                    dp[i] = 0;
                } else if (words_in_line == 1) {
                    // Only one word, must fill entire line
                    // This means it must be exactly W characters
                    if (len[i] == W) {
                        dp[i] = min(dp[i], dp[j + 1]);
                    }
                } else {
                    // Multiple words, need to distribute spaces
                    int remaining_spaces = W - (total_len - (words_in_line - 1));
                    int gaps = words_in_line - 1;

                    // Each gap gets at least 1 space
                    // We need to distribute remaining_spaces spaces among gaps
                    int min_gap = remaining_spaces / gaps;
                    int max_gap = (remaining_spaces + gaps - 1) / gaps;

                    if (max_gap <= mid) {
                        dp[i] = min(dp[i], max(dp[j + 1], max_gap));
                    }
                }
            }
        }

        if (dp[0] <= mid) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    cout << ans << "\n";

    return 0;
}

