static const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W;
    if (!(cin >> W)) return 0;

    vector<string> words;
    string s;
    while (cin >> s) words.push_back(s);

    int n = (int)words.size();
    if (n == 0) {
        cout << 0 << "\n";
        return 0;
    }

    vector<int> len(n + 1), pref(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        len[i] = (int)words[i - 1].size();
        pref[i] = pref[i - 1] + len[i];
    }

    auto sumLen = [&](int l, int r) -> int {
        return pref[r] - pref[l - 1];
    };

    // cost[l][r]:
    // If words l..r can be placed on one line:
    // - if r == n (last line): cost = 1 if more than one word, else 0
    // - otherwise:
    //      one word: valid only if len == W, cost = 0
    //      >=2 words: extra spaces distributed among gaps, minimal possible max gap
    //                 equals ceil(total_spaces / gaps)
    // invalid => INF
    vector<vector<int>> cost(n + 2, vector<int>(n + 2, INF));

    for (int l = 1; l <= n; ++l) {
        for (int r = l; r <= n; ++r) {
            int k = r - l + 1;
            int letters = sumLen(l, r);
            int minWidth = letters + (k - 1); // at least one space per gap
            if (minWidth > W) break;

            if (r == n) {
                // Last line: only needs at least one space between words, no full justification.
                cost[l][r] = (k == 1 ? 0 : 1);
            } else {
                if (k == 1) {
                    if (letters == W) cost[l][r] = 0;
                } else {
                    int gaps = k - 1;
                    int totalSpaces = W - letters;
                    // Need positive spaces in each gap, possible since minWidth <= W.
                    cost[l][r] = (totalSpaces + gaps - 1) / gaps;
                }
            }
        }
    }

    // DP: dp[i] = minimal possible answer for words i..n
    vector<int> dp(n + 2, INF);
    dp[n + 1] = 0;

    for (int i = n; i >= 1; --i) {
        for (int j = i; j <= n; ++j) {
            if (cost[i][j] == INF) continue;
            dp[i] = min(dp[i], max(cost[i][j], dp[j + 1]));
        }
    }

    if (dp[1] >= INF) cout << "impossible\n";
    else cout << dp[1] << "\n";

    return 0;
}

