public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null && line.trim().isEmpty()) {
            // skip empty lines
        }
        if (line == null) return;
        String[] parts = line.split(" ", 2);
        int W = Integer.parseInt(parts[0]);
        String text = parts[1];
        String[] words = text.split(" ");
        int n = words.length;
        int[] len = new int[n];
        for (int i = 0; i < n; i++) {
            len[i] = words[i].length();
        }

        // dp[i] = minimal possible maximum space gap for words from i to end
        // We'll store the result and also the next line break position
        int[] dp = new int[n + 1];
        int[] next = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[n] = 0;
        next[n] = n;

        for (int i = n - 1; i >= 0; i--) {
            int totalLen = 0;
            // try to put words i..j on current line
            for (int j = i; j < n; j++) {
                totalLen += len[j];
                int gaps = j - i;
                if (totalLen + gaps > W) break;
                if (j == n - 1) {
                    // last line: no justification needed
                    int candidate = Math.max(dp[j + 1], 0);
                    if (candidate < dp[i]) {
                        dp[i] = candidate;
                        next[i] = j + 1;
                    }
                } else {
                    int spaces = W - totalLen;
                    int numGaps = gaps;
                    if (numGaps == 0) continue; // single word line not allowed except last line
                    int minGap = spaces / numGaps;
                    int extra = spaces % numGaps;
                    // The maximum gap on this line is minGap + (extra > 0 ? 1 : 0)
                    int maxGap = minGap + (extra > 0 ? 1 : 0);
                    int candidate = Math.max(maxGap, dp[j + 1]);
                    if (candidate < dp[i]) {
                        dp[i] = candidate;
                        next[i] = j + 1;
                    }
                }
            }
        }

        // Build output
        int idx = 0;
        StringBuilder sb = new StringBuilder();
        while (idx < n) {
            int end = next[idx];
            // build line from idx to end-1
            int totalLen = 0;
            for (int k = idx; k < end; k++) {
                totalLen += len[k];
            }
            int gaps = end - idx - 1;
            if (end == n) {
                // last line: left justified
                for (int k = idx; k < end; k++) {
                    if (k > idx) sb.append(' ');
                    sb.append(words[k]);
                }
                sb.append('\n');
            } else {
                int spaces = W - totalLen;
                int numGaps = gaps;
                int minGap = spaces / numGaps;
                int extra = spaces % numGaps;
                for (int k = idx; k < end; k++) {
                    if (k > idx) {
                        int gap = minGap + (k - idx <= extra ? 1 : 0);
                        for (int s = 0; s < gap; s++) sb.append(' ');
                    }
                    sb.append(words[k]);
                }
                sb.append('\n');
            }
            idx = end;
        }
        System.out.print(sb.toString());
    }
}

