        Scanner sc = new Scanner(System.in);
        int W = sc.nextInt();
        List<String> words = new ArrayList<>();
        while (sc.hasNext()) words.add(sc.next());
        int n = words.size();
        int[] len = new int[n];
        for (int i = 0; i < n; i++) len[i] = words.get(i).length();
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i+1] = prefix[i] + len[i];

        int[] dp = new int[n + 1];
        int[] from = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE / 2);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            if (dp[i] == Integer.MAX_VALUE / 2) continue;
            for (int j = i + 1; j <= n; j++) {
                int totalLen = prefix[j] - prefix[i];
                int gaps = j - i - 1;
                int minLen = totalLen + gaps;
                if (minLen > W) break;
                int cost;
                if (j == n) { // last line
                    cost = gaps > 0 ? 1 : 0;
                } else {
                    int rem = W - totalLen;
                    cost = gaps == 0 ? (totalLen == W ? 0 : Integer.MAX_VALUE / 2) : (rem + gaps - 1) / gaps;
                }
                int newVal = Math.max(dp[i], cost);
                if (newVal < dp[j]) { dp[j] = newVal; from[j] = i; }
            }
        }
        // reconstruct and print
        // ... build lines
        List<int[]> lines = new ArrayList<>();
        int cur = n;
        while (cur > 0) { lines.add(new int[]{from[cur], cur}); cur = from[cur]; }
        Collections.reverse(lines);
        StringBuilder sb = new StringBuilder();
        for (int li = 0; li < lines.size(); li++) {
            int s = lines.get(li)[0], e = lines.get(li)[1];
            boolean isLast = li == lines.size() - 1;
            int totalLen = prefix[e] - prefix[s];
            int gaps = e - s - 1;
            StringBuilder line = new StringBuilder();
            for (int i = s; i < e; i++) {
                line.append(words.get(i));
                if (i < e - 1) {
                    int rem = W - totalLen;
                    int sp;
                    if (isLast) sp = 1;
                    else if (gaps == 0) sp = 0;
                    else { int g = i - s; sp = rem/gaps + (g < rem%gaps ? 1 : 0); }
                    for (int k = 0; k < sp; k++) line.append(' ');
                }
            }
            sb.append(line).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int W, n;
    static int[] len;
    static boolean[][] ok;
    static int[] pref;

    static int sumLen(int l, int r) {
        return pref[r + 1] - pref[l];
    }

    static boolean canPlace(int l, int r, int M) {
        if (!ok[l][r]) return false;
        int k = r - l + 1;
        if (r == n - 1) {
            // Last line: only need at least one space between words, no full justification.
            return true;
        }
        if (k == 1) {
            // Non-last line with one word must start at col 1 and end at col W.
            return len[l] == W;
        }
        int spaces = W - sumLen(l, r);
        int gaps = k - 1;
        if (spaces < gaps) return false;
        int maxGap = (spaces + gaps - 1) / gaps; // ceil
        return maxGap <= M;
    }

    static boolean feasible(int M) {
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 0; i < n; i++) {
            if (!dp[i]) continue;
            for (int j = i; j < n; j++) {
                if (!canPlace(i, j, M)) continue;
                dp[j + 1] = true;
            }
        }
        return dp[n];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        W = Integer.parseInt(first);
        List<Integer> words = new ArrayList<>();
        String s;
        while ((s = fs.next()) != null) words.add(s.length());

        n = words.size();
        len = new int[n];
        for (int i = 0; i < n; i++) len[i] = words.get(i);

        pref = new int[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + len[i];

        ok = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            int total = 0;
            for (int j = i; j < n; j++) {
                total += len[j];
                int minWidth = total + (j - i); // at least one space between words
                if (minWidth <= W) ok[i][j] = true;
                else break;
            }
        }

        int lo = 1, hi = W, ans = W;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (feasible(mid)) {
                ans = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }

        System.out.println(ans);
    }
}

import sys

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    W = int(data[0].strip())
    text = data[1].strip()
    words = text.split()

    lines = []
    current_line = []
    current_len = 0

    for word in words:
        if current_line:
            # need at least 1 space before word
            if current_len + 1 + len(word) <= W:
                current_line.append(word)
                current_len += 1 + len(word)
            else:
                lines.append(current_line)
                current_line = [word]
                current_len = len(word)
        else:
            current_line = [word]
            current_len = len(word)

    if current_line:
        lines.append(current_line)

    result_lines = []
    for idx, line_words in enumerate(lines):
        if idx == len(lines) - 1:
            # last line: left-justified
            line_str = ' '.join(line_words)
            line_str += ' ' * (W - len(line_str))
            result_lines.append(line_str)
        else:
            total_chars = sum(len(w) for w in line_words)
            spaces_needed = W - total_chars
            gaps = len(line_words) - 1
            if gaps == 0:
                # single word line, left-justify
                line_str = line_words[0] + ' ' * (W - len(line_words[0]))
                result_lines.append(line_str)
            else:
                base_spaces = spaces_needed // gaps
                extra_spaces = spaces_needed % gaps
                line_parts = []
                for i, w in enumerate(line_words[:-1]):
                    line_parts.append(w)
                    if i < extra_spaces:
                        line_parts.append(' ' * (base_spaces + 1))
                    else:
                        line_parts.append(' ' * base_spaces)
                line_parts.append(line_words[-1])
                result_lines.append(''.join(line_parts))

    sys.stdout.write('\n'.join(result_lines))

