import sys
from math import ceil

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    W = int(input_data[idx]); idx += 1
    N = int(input_data[idx]); idx += 1
    words = []
    for i in range(N):
        words.append(input_data[idx]); idx += 1

    lens = [len(w) for w in words]
    prefix = [0] * (N + 1)
    for i in range(N):
        prefix[i+1] = prefix[i] + lens[i]

    def sum_len(i, j):  # words i..j-1
        return prefix[j] - prefix[i]

    def line_cost(i, j):  # words i..j-1 on non-last line
        s = sum_len(i, j)
        gaps = j - i - 1
        spaces = W - s
        if spaces < 0:
            return float('inf')
        if gaps == 0:
            return 0 if spaces == 0 else float('inf')
        if spaces < gaps:
            return float('inf')
        return ceil(spaces / gaps)

    # Binary search on max gap
    def feasible(g):
        # dp[i] = True if words 0..i-1 can be laid out
        dp = [False] * (N + 1)
        dp[0] = True
        for j in range(1, N + 1):
            for i in range(j, 0, -1):
                if not dp[i-1]:
                    continue
                s = sum_len(i-1, j)
                if s > W:
                    break
                if j == N:  # last line
                    if s + (j - i) <= W:
                        dp[j] = True
                else:
                    c = line_cost(i-1, j)
                    if c <= g:
                        dp[j] = True
        return dp[N]

    lo, hi = 1, W
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1

    print(lo)

solve()
